def fetch_attendance_data(supabase_url: str, supabase_key: str, target_date: str):
    """Fetch pointage data for the given date from primary Supabase."""
    sb = create_client(supabase_url, supabase_key)
    
    res = sb.table("pointages").select("*").eq("date", target_date).execute()
    data = res.data or []
    
    if not data:
        return {}
    
    groups = {}
    for record in data:
        grp = record.get("group") or "SANS GROUPE"
        if grp not in groups:
            groups[grp] = []
        groups[grp].append(record)
        
    for grp in groups:
        groups[grp].sort(key=lambda x: (x.get("name") or "", x.get("matricule") or ""))
        
    return groups

def round_punch_time(dt: datetime) -> str:
    """
    Round check-in / check-out time according to user specification:
    - Minutes :15 to :44 -> rounded to :30 (e.g. 6:16 -> 6:30, 6:43 -> 6:30)
    - Minutes :45 to :14 -> rounded to :00 of nearest hour (e.g. 6:10 -> 6:00, 6:49 -> 7:00)
    """
    h = dt.hour
    m = dt.minute
    if 15 <= m <= 44:
        return f"{h:02d}:30"
    elif 45 <= m <= 59:
        next_h = (h + 1) % 24
        return f"{next_h:02d}:00"
    else:  # 0 <= m <= 14
        return f"{h:02d}:00"

def fetch_external_biometric_punches(target_date: str):
    """
    Fetch raw biometric device check-in/out timestamps from external Supabase database.
    Applies Night Shift rule (check-in after 20:00 previous evening) and minute rounding rule.
    """
    try:
        target_dt = datetime.strptime(target_date, '%Y-%m-%d')
        prev_dt = target_dt - timedelta(days=1)
        prev_date_str = prev_dt.strftime('%Y-%m-%d')
        
        # Query punches from prev_date 20:00:00Z to target_date 23:59:59Z to cover night shifts starting after 20:00
        url = f"{EXTERNAL_SUPABASE_URL}/rest/v1/pointages?select=user_id,timestamp&timestamp=gte.{prev_date_str}T20:00:00Z&timestamp=lte.{target_date}T23:59:59Z&order=timestamp.asc"
        headers = {
            'apikey': EXTERNAL_SUPABASE_KEY,
            'Authorization': f'Bearer {EXTERNAL_SUPABASE_KEY}'
        }
        
        res = requests.get(url, headers=headers, timeout=15)
        if res.status_code != 200:
            print(f"⚠️ External DB fetch returned HTTP {res.status_code}: {res.text[:200]}")
            return {}
            
        data = res.json()
        if not isinstance(data, list):
            return {}
            
        user_punches = {}
        for r in data:
            uid = str(r.get('user_id', '')).strip()
            ts_str = r.get('timestamp')
            if not uid or not ts_str:
                continue
            if uid not in user_punches:
                user_punches[uid] = []
            try:
                user_punches[uid].append(datetime.fromisoformat(ts_str.replace('Z', '+00:00')))
            except Exception:
                pass
                
        result = {}
        for uid, punches in user_punches.items():
            # Check for Night Shift check-in (punch after 20:00 on prev_date)
            night_in_punches = [p for p in punches if p.strftime('%Y-%m-%d') == prev_date_str and p.hour >= 20]
            
            if night_in_punches:
                t_in = night_in_punches[0]
                night_out_punches = [p for p in punches if p.strftime('%Y-%m-%d') == target_date and p.hour < 12]
                if night_out_punches:
                    t_out = night_out_punches[-1]
                    rnd_in = round_punch_time(t_in)
                    rnd_out = round_punch_time(t_out)
                    
                    in_dt = datetime.strptime(f"{prev_date_str} {rnd_in}", "%Y-%m-%d %H:%M")
                    out_dt = datetime.strptime(f"{target_date} {rnd_out}", "%Y-%m-%d %H:%M")
                    diff_hours = (out_dt - in_dt).total_seconds() / 3600.0
                    
                    result[uid] = {
                        'entrer': rnd_in,
                        'sortie': rnd_out,
                        'real_hours': max(diff_hours, 0.0),
                        'is_night_shift': True
                    }
                    continue
            
            # Standard Day Shift on target_date
            target_punches = [p for p in punches if p.strftime('%Y-%m-%d') == target_date]
            if target_punches:
                t_in = target_punches[0]
                t_out = target_punches[-1] if len(target_punches) >= 2 else None
                rnd_in = round_punch_time(t_in)
                if t_out:
                    rnd_out = round_punch_time(t_out)
                    in_dt = datetime.strptime(f"{target_date} {rnd_in}", "%Y-%m-%d %H:%M")
                    out_dt = datetime.strptime(f"{target_date} {rnd_out}", "%Y-%m-%d %H:%M")
                    diff_hours = (out_dt - in_dt).total_seconds() / 3600.0
                else:
                    rnd_out = "--:--"
                    diff_hours = 0.0
                    
                result[uid] = {
                    'entrer': rnd_in,
                    'sortie': rnd_out,
                    'real_hours': max(diff_hours, 0.0),
                    'is_night_shift': False
                }

        return result
    except Exception as e:
        print(f"⚠️ Failed to fetch external biometric punches: {e}")
        return {}

def format_hours(val: float) -> str:
    """Format hour number cleanly (e.g. 5.5, 8.0, 38.5)."""
    return f"{val:.1f}"

def create_attendance_pdf(groups_data: dict, target_date: str, output_path: str, chef_ferme: str = "ABDELKABIR NADIF"):
    """
    Generate Fiche 3 'TRAVALE A LA TACHE' PDF matching exact HTML print template layout.
    Applies uniform Group Entry & Exit Times (group majority mode) and half-hour rounding rules.
    """
    
    print(f"🔄 Fetching raw biometric punches from external database ({EXTERNAL_SUPABASE_URL})...")
    biometric_data = fetch_external_biometric_punches(target_date)
    print(f"✅ Real biometric punches fetched for {len(biometric_data)} worker(s).")
    
    doc = SimpleDocTemplate(
        output_path,
        pagesize=A4,
        leftMargin=1.2 * cm,
        rightMargin=1.2 * cm,
        topMargin=1.0 * cm,
        bottomMargin=1.0 * cm
    )
    
    styles = getSampleStyleSheet()
    
    title_style = ParagraphStyle(
        'HeaderTitle',
        parent=styles['Normal'],
        fontName='Helvetica-Bold',
        fontSize=14,
        leading=16,
        textColor=colors.black,
        alignment=1 # Center
    )
    
    header_right_style = ParagraphStyle(
        'HeaderRight',
        parent=styles['Normal'],
        fontName='Helvetica',
        fontSize=10,
        leading=13,
        textColor=colors.black,
        alignment=2 # Right
    )
    
    meta_label = ParagraphStyle(
        'MetaLabel',
        parent=styles['Normal'],
        fontName='Helvetica-Bold',
        fontSize=9,
        leading=11,
        textColor=colors.black
    )
    
    meta_val = ParagraphStyle(
        'MetaVal',
        parent=styles['Normal'],
        fontName='Helvetica',
        fontSize=9,
        leading=11,
        textColor=colors.black
    )
    
    th_style = ParagraphStyle(
        'TableHeader',
        parent=styles['Normal'],
        fontName='Helvetica-Bold',
        fontSize=8,
        leading=10,
        textColor=colors.black,
        alignment=1 # Center
    )
    
    td_style = ParagraphStyle(
        'TableCell',
        parent=styles['Normal'],
        fontName='Helvetica',
        fontSize=8.5,
        leading=11,
        textColor=colors.black
    )
    
    td_center = ParagraphStyle(
        'TableCellCenter',
        parent=td_style,
        alignment=1 # Center
    )
    
    summary_style = ParagraphStyle(
        'SummaryStyle',
        parent=styles['Normal'],
        fontName='Helvetica',
        fontSize=9,
        leading=14,
        textColor=colors.black
    )
    
    story = []
    sorted_group_names = sorted(groups_data.keys())
    total_groups = len(sorted_group_names)
    
    for idx, grp_name in enumerate(sorted_group_names):
        workers = groups_data[grp_name]
        total_workers = len(workers)
        
        # 1. Determine group uniform/majority entry time (ENTRER) and exit time (SORTIE)
        group_in_times = []
        group_out_times = []
        group_night_flags = []
        
        for w in workers:
            mat = str(w.get("matricule", "")).strip()
            if mat in biometric_data:
                group_in_times.append(biometric_data[mat]["entrer"])
                group_out_times.append(biometric_data[mat]["sortie"])
                group_night_flags.append(biometric_data[mat].get("is_night_shift", False))
                
        # Majority mode for group ENTRER and SORTIE
        if group_in_times:
            group_majority_in = max(set(group_in_times), key=group_in_times.count)
        else:
            group_majority_in = "07:00"
            
        if group_out_times:
            group_majority_out = max(set(group_out_times), key=group_out_times.count)
        else:
            group_majority_out = "12:30"
            
        is_group_night = (group_night_flags.count(True) > len(group_night_flags) / 2) if group_night_flags else False
        
        # Calculate group uniform TH RÉEL from group_majority_in to group_majority_out
        try:
            target_dt = datetime.strptime(target_date, '%Y-%m-%d')
            if is_group_night:
                prev_dt = target_dt - timedelta(days=1)
                in_dt = datetime.strptime(f"{prev_dt.strftime('%Y-%m-%d')} {group_majority_in}", "%Y-%m-%d %H:%M")
            else:
                in_dt = datetime.strptime(f"{target_date} {group_majority_in}", "%Y-%m-%d %H:%M")
                
            out_dt = datetime.strptime(f"{target_date} {group_majority_out}", "%Y-%m-%d %H:%M")
            group_real_h = round(((out_dt - in_dt).total_seconds() / 3600.0) * 2) / 2.0
            if group_real_h <= 0:
                group_real_h = 5.5
        except Exception:
            group_real_h = 5.5
            
        processed_workers = []
        for w in workers:
            mat = str(w.get("matricule", "")).strip()
            task_h = float(w.get("hours") or 8.0)
            
            # Apply group uniform ENTRER, SORTIE, and TH RÉEL unless group is VARIABLE
            if "VARIABLE" in grp_name.upper() and mat in biometric_data:
                entrer = biometric_data[mat]["entrer"]
                sortie = biometric_data[mat]["sortie"]
                real_h = biometric_data[mat]["real_hours"]
            else:
                entrer = group_majority_in
                sortie = group_majority_out
                real_h = group_real_h
                
            processed_workers.append({
                "matricule": mat,
                "name": w.get("name", ""),
                "entrer": entrer,
                "sortie": sortie,
                "real_hours": real_h,
                "task_hours": task_h
            })
            
        total_real_hours = sum(pw["real_hours"] for pw in processed_workers)
        total_task_hours = sum(pw["task_hours"] for pw in processed_workers)
        
        logo_img = get_logo_image()
            
        header_data = [
            [
                logo_img,
                Paragraph("<b>TRAVALE A LA TACHE</b>", title_style),
                Paragraph(f"FINCA: 20<br/>DATE: {target_date}", header_right_style)
            ]
        ]
        header_table = Table(header_data, colWidths=[5.0*cm, 8.6*cm, 5.0*cm])
        header_table.setStyle(TableStyle([
            ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
            ('ALIGN', (0,0), (0,0), 'LEFT'),
            ('ALIGN', (1,0), (1,0), 'CENTER'),
            ('ALIGN', (2,0), (2,0), 'RIGHT'),
            ('BOTTOMPADDING', (0,0), (-1,-1), 2),
        ]))
        story.append(header_table)
        story.append(Spacer(1, 0.3*cm))
        
        meta_data = [
            [
                Paragraph("<b>TÂCHE:</b>", meta_label),
                Paragraph("TOUT LES OPERATION", meta_val),
                Paragraph("<b>ÉQUIPE / ENCARGADO:</b>", meta_label),
                Paragraph(f"{grp_name}", meta_val),
            ],
            [
                Paragraph("<b>N° ouvriers:</b>", meta_label),
                Paragraph(f"{total_workers}", meta_val),
                Paragraph("<b>Total heures travaillées:</b>", meta_label),
                Paragraph(f"{format_hours(total_real_hours)}", meta_val),
            ]
        ]
        meta_table = Table(meta_data, colWidths=[2.2*cm, 5.5*cm, 4.6*cm, 6.3*cm])
        meta_table.setStyle(TableStyle([
            ('GRID', (0,0), (-1,-1), 1, colors.black),
            ('TOPPADDING', (0,0), (-1,-1), 6),
            ('BOTTOMPADDING', (0,0), (-1,-1), 6),
            ('LEFTPADDING', (0,0), (-1,-1), 6),
            ('RIGHTPADDING', (0,0), (-1,-1), 6),
            ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
        ]))
        story.append(meta_table)
        story.append(Spacer(1, 0.35*cm))
        
        col_widths = [1.8*cm, 6.4*cm, 1.8*cm, 1.8*cm, 2.0*cm, 4.8*cm]
        table_rows = [
            [
                Paragraph("<b>CODE</b>", th_style),
                Paragraph("<b>NOM ET PRÉNOM</b>", th_style),
                Paragraph("<b>ENTRER</b>", th_style),
                Paragraph("<b>SORTIE</b>", th_style),
                Paragraph("<b>TH RÉEL</b>", th_style),
                Paragraph("<b>TH À CAUSE DE TRAVAILLER À LA TÂCHE</b>", th_style),
            ]
        ]
        
        for pw in processed_workers:
            table_rows.append([
                Paragraph(pw["matricule"], td_center),
                Paragraph(pw["name"], td_style),
                Paragraph(pw["entrer"], td_center),
                Paragraph(pw["sortie"], td_center),
                Paragraph(format_hours(pw["real_hours"]), td_center),
                Paragraph(format_hours(pw["task_hours"]), td_center),
            ])
            
        form_table = Table(table_rows, colWidths=col_widths, repeatRows=1)
        form_table.setStyle(TableStyle([
            ('GRID', (0,0), (-1,-1), 1, colors.black),
            ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
            ('TOPPADDING', (0,0), (-1,-1), 5),
            ('BOTTOMPADDING', (0,0), (-1,-1), 5),
            ('LEFTPADDING', (0,0), (-1,-1), 5),
            ('RIGHTPADDING', (0,0), (-1,-1), 5),
        ]))
        story.append(form_table)
        story.append(Spacer(1, 0.35*cm))
        
        summary_data = [
            [
                Paragraph(f"Total des heures travaillées (RÉEL): {format_hours(total_real_hours)}", summary_style),
                Paragraph(f"Totale heure pointée par responsable ferme: {format_hours(total_task_hours)}", summary_style),
            ],
            [
                Paragraph("QUANTITE KG:", summary_style),
                Paragraph("RENDEMENT KG/H:", summary_style),
            ]
        ]
        summary_table = Table(summary_data, colWidths=[9.3*cm, 9.3*cm])
        summary_table.setStyle(TableStyle([
            ('VALIGN', (0,0), (-1,-1), 'TOP'),
            ('TOPPADDING', (0,0), (-1,-1), 2),
            ('BOTTOMPADDING', (0,0), (-1,-1), 2),
            ('LEFTPADDING', (0,0), (-1,-1), 0),
            ('RIGHTPADDING', (0,0), (-1,-1), 0),
        ]))
        story.append(summary_table)
        story.append(Spacer(1, 0.4*cm))
        
        sig_box_data = [
            [Paragraph("<b>Signature Chef ferme</b>", ParagraphStyle('SigTitle', fontName='Helvetica-Bold', fontSize=9, textColor=colors.black))]
        ]
        sig_box_table = Table(sig_box_data, colWidths=[18.6*cm], rowHeights=[2.3*cm])
        sig_box_table.setStyle(TableStyle([
            ('GRID', (0,0), (-1,-1), 1, colors.black),
            ('VALIGN', (0,0), (-1,-1), 'TOP'),
            ('TOPPADDING', (0,0), (-1,-1), 6),
            ('LEFTPADDING', (0,0), (-1,-1), 8),
        ]))
        
        sig_block = KeepTogether([
            sig_box_table,
            Spacer(1, 0.15*cm),
            Paragraph(f"Nom & prénom : {chef_ferme}", ParagraphStyle('ChefName', fontName='Helvetica', fontSize=9, textColor=colors.black))
        ])
        
        story.append(sig_block)
        
        if idx < total_groups - 1:
            story.append(PageBreak())
            
    doc.build(story)
    print(f"✅ PDF 'Fiche 3: TRAVALE A LA TACHE' generated: {output_path} ({total_groups} groups)")

def get_telegram_updates(bot_token: str):
    """Fetch recent messages sent to the Telegram bot to discover active chats."""
    url = f"https://api.telegram.org/bot{bot_token}/getUpdates"
    try:
        res = requests.get(url).json()
        if not res.get("ok"):
            print(f"❌ Error from Telegram: {res.get('description')}")
            return []
        
        results = res.get("result", [])
        chats = []
        seen = set()
        for item in reversed(results):
            msg = item.get("message") or item.get("channel_post") or {}
            chat = msg.get("chat", {})
            chat_id = chat.get("id")
            if chat_id and chat_id not in seen:
                seen.add(chat_id)
                chat_title = chat.get("title") or f"{chat.get('first_name', '')} {chat.get('last_name', '')}".strip() or "Private Chat"
                chat_type = chat.get("type", "unknown")
                chats.append({
                    "id": chat_id,
                    "title": chat_title,
                    "type": chat_type,
                    "date": msg.get("date")
                })
        return chats
    except Exception as e:
        print(f"❌ Failed to fetch Telegram updates: {e}")
        return []

def send_pdf_to_telegram(pdf_path: str, bot_token: str, chat_id: str, caption: str, max_retries: int = 3):
    """Send the PDF file to a Telegram group/chat via Telegram Bot API with automatic retries and progress logs."""
    if not bot_token or not chat_id:
        print("⚠️ Telegram BOT_TOKEN or CHAT_ID is missing. Skipping Telegram notification.")
        return False
        
    url = f"https://api.telegram.org/bot{bot_token}/sendDocument"
    file_size_kb = os.path.getsize(pdf_path) / 1024
    
    print(f"📤 Preparing to send PDF ({file_size_kb:.1f} KB) to Telegram Chat ID: {chat_id}...")
    
    session = requests.Session()
    
    for attempt in range(1, max_retries + 1):
        try:
            print(f"⏳ Uploading to Telegram (Attempt {attempt}/{max_retries})... Please wait.")
            with open(pdf_path, 'rb') as f:
                files = {'document': (os.path.basename(pdf_path), f, 'application/pdf')}
                data = {
                    'chat_id': chat_id,
                    'caption': caption,
                    'parse_mode': 'Markdown'
                }
                res = session.post(url, data=data, files=files, timeout=60)
                res_json = res.json()
                
            if res.status_code == 200 and res_json.get('ok'):
                msg_id = res_json.get('result', {}).get('message_id')
                chat_title = res_json.get('result', {}).get('chat', {}).get('title', 'Chat')
                print(f"🚀 Telegram document sent successfully to '{chat_title}' (Message ID: {msg_id})!")
                return True
            else:
                desc = res_json.get('description', res.text)
                print(f"⚠️ Telegram API response (Attempt {attempt}/{max_retries}): {desc}")
        except Exception as e:
            print(f"⚠️ Network error sending to Telegram (Attempt {attempt}/{max_retries}): {e}")
            
    print(f"❌ Failed to send document to Telegram after {max_retries} attempts.")
    return False

def fetch_pending_scheduled_dates(url: str, key: str):
    """Fetch pending queued dates from Supabase table 'form_templates'."""
    try:
        # Check external Supabase first
        res = requests.get(
            f"{EXTERNAL_SUPABASE_URL}/rest/v1/form_templates?category=eq.SCHEDULED_TELEGRAM_DATE&select=id,name,payload",
            headers={"apikey": EXTERNAL_SUPABASE_KEY, "Authorization": f"Bearer {EXTERNAL_SUPABASE_KEY}"}
        )
        if res.status_code == 200 and res.json():
            return res.json(), EXTERNAL_SUPABASE_URL, EXTERNAL_SUPABASE_KEY
            
        # Fallback to primary Supabase
        res_prim = requests.get(
            f"{url}/rest/v1/form_templates?category=eq.SCHEDULED_TELEGRAM_DATE&select=id,name,payload",
            headers={"apikey": key, "Authorization": f"Bearer {key}"}
        )
        if res_prim.status_code == 200 and res_prim.json():
            return res_prim.json(), url, key
            
        return [], url, key
    except Exception as e:
        print(f"⚠️ Error checking scheduled dates queue in Supabase: {e}")
        return [], url, key

def delete_scheduled_date(url: str, key: str, row_id: str):
    """Delete processed scheduled date from Supabase queue table."""
    try:
        res = requests.delete(
            f"{url}/rest/v1/form_templates?id=eq.{row_id}",
            headers={"apikey": key, "Authorization": f"Bearer {key}"}
        )
        if res.status_code in [200, 204]:
            print(f"🗑️ Cleaned up processed scheduled date row (ID: {row_id}) from Supabase.")
            return True
        else:
            print(f"⚠️ Failed to delete scheduled date row {row_id}: {res.status_code} {res.text}")
            return False
    except Exception as e:
        print(f"⚠️ Error deleting scheduled date {row_id} from Supabase: {e}")
        return False

def main():
    parser = argparse.ArgumentParser(description="Generate Fiche 3 'TRAVALE A LA TACHE' PDF and Send to Telegram.")
    parser.add_argument("--date", type=str, help="Target date in YYYY-MM-DD format (default: yesterday)")
    parser.add_argument("--bot-token", type=str, default=TELEGRAM_BOT_TOKEN, help="Telegram Bot Token")
    parser.add_argument("--chat-id", type=str, default=TELEGRAM_CHAT_ID, help="Telegram Chat ID")
    parser.add_argument("--chef", type=str, default="ABDELKABIR NADIF", help="Chef ferme name")
    parser.add_argument("--output", type=str, help="Output PDF file path")
    parser.add_argument("--dry-run", action="store_true", help="Generate PDF without sending to Telegram")
    parser.add_argument("--check-chats", action="store_true", help="List recent Telegram chats messaged to bot")
    
    args = parser.parse_args()
    
    if args.check_chats:
        print(f"🔍 Checking recent chats for Bot token: {args.bot_token[:15]}...")
        chats = get_telegram_updates(args.bot_token)
        if not chats:
            print("⚠️ No recent chats found. Send a message (e.g. 'hi') to your Telegram bot or group first!")
        else:
            print(f"📋 Found {len(chats)} recent chat(s):")
            for c in chats:
                print(f"  • Title: {c['title']} | Type: {c['type']} | Chat ID: {c['id']}")
        return

    # Check if there are queued dates in Supabase table 'form_templates'
    if not args.date:
        queued_items, active_url, active_key = fetch_pending_scheduled_dates(DEFAULT_SUPABASE_URL, DEFAULT_SUPABASE_KEY)
        if queued_items:
            print(f"📥 Found {len(queued_items)} scheduled date(s) in Supabase queue ({active_url})!")
            for item in queued_items:
                row_id = item['id']
                target_date = item['name']
                print(f"\n==================================================")
                print(f"🚀 Processing Queued Scheduled Date: {target_date}")
                print(f"==================================================")
                output_pdf = f"travail_a_la_tache_{target_date}.pdf"
                groups_data = fetch_attendance_data(DEFAULT_SUPABASE_URL, DEFAULT_SUPABASE_KEY, target_date)
                
                if not groups_data:
                    print(f"⚠️ No pointages data found for queued date {target_date}. Cleaning up queue row...")
                    delete_scheduled_date(active_url, active_key, row_id)
                    continue
                    
                create_attendance_pdf(groups_data, target_date, output_pdf, chef_ferme=args.chef)
                total_workers = sum(len(workers) for workers in groups_data.values())
                caption = (
                    f"📋 *Fiche Travail à la Tâche - Ferme F20*\n"
                    f"📅 *Date:* `{target_date}`\n"
                    f"👥 *Nombre d'équipes:* {len(groups_data)}\n"
                    f"👷 *Total ouvriers:* {total_workers}\n\n"
                    f"✅ Rapport généré depuis la file d'attente Supabase."
                )
                if not args.dry_run:
                    success = send_pdf_to_telegram(output_pdf, args.bot_token, args.chat_id, caption)
                    if success:
                        delete_scheduled_date(active_url, active_key, row_id)
                else:
                    print("🧪 Dry-run mode active. Skipping Telegram upload and queue deletion.")
            print("\n🎉 All queued dates processed and cleared from Supabase!")
            return
        else:
            print("ℹ️ Aucun تاريخ مجدول في جدول Supabase. لا توجد تواريخ للمعالجة.")
            return



    # Single date execution mode (command line argument or yesterday default)
    if args.date:
        target_date = args.date
    else:
        yesterday_dt = datetime.now() - timedelta(days=1)
        target_date = yesterday_dt.strftime("%Y-%m-%d")
        
    print(f"📅 Target Date: {target_date}")
    output_pdf = args.output or f"travail_a_la_tache_{target_date}.pdf"
    
    print(f"🔄 Fetching pointages for date: {target_date}...")
    groups_data = fetch_attendance_data(DEFAULT_SUPABASE_URL, DEFAULT_SUPABASE_KEY, target_date)
    
    if not groups_data:
        print(f"⚠️ No pointages found for date {target_date}.")
        print("Checking if there are pointages for other recent dates...")
        sb = create_client(DEFAULT_SUPABASE_URL, DEFAULT_SUPABASE_KEY)
        res = sb.table("pointages").select("date").order("date", desc=True).limit(10).execute()
        recent_dates = list(dict.fromkeys([r['date'] for r in res.data])) if res.data else []
        if recent_dates:
            print(f"💡 Recent available dates in database: {', '.join(recent_dates[:5])}")
            print(f"Running fallback for latest available date: {recent_dates[0]}...")
            target_date = recent_dates[0]
            output_pdf = f"travail_a_la_tache_{target_date}.pdf"
            groups_data = fetch_attendance_data(DEFAULT_SUPABASE_URL, DEFAULT_SUPABASE_KEY, target_date)
            
    if not groups_data:
        print("❌ No pointages data found to generate PDF.")
        sys.exit(1)
        
    create_attendance_pdf(groups_data, target_date, output_pdf, chef_ferme=args.chef)
    
    total_workers = sum(len(workers) for workers in groups_data.values())
    caption = (
        f"📋 *Fiche Travail à la Tâche - Ferme F20*\n"
        f"📅 *Date:* `{target_date}`\n"
        f"👥 *Nombre d'équipes:* {len(groups_data)}\n"
        f"👷 *Total ouvriers:* {total_workers}\n\n"
        f"✅ Rapport généré automatiquement depuis Supabase."
    )
    
    if not args.dry_run:
        send_pdf_to_telegram(output_pdf, args.bot_token, args.chat_id, caption)
    else:
        print(f"🧪 Dry-run mode active. PDF saved at '{output_pdf}' (Telegram send skipped).")

if __name__ == "__main__":
    main()
